import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
  signal,
} from '@angular/core';
import { ChartLegend, type ChartLegendItem } from './chart-legend';
import { ChartFrame } from '../headless/chart-frame';
import { Pie } from '../headless/pie';
import { formatValue } from '../headless/format';
import {
  paletteColor,
  type ChartConfig,
  type ChartDatum,
} from '../headless/types';

interface LegendItem {
  name: string;
  color: string;
}

/**
 * Styled pie / donut chart — parity with `@gremorie/rx-data`'s `PieChart`.
 * `nameKey` is the slice label field, `dataKey` the numeric value field. Slice
 * colors come from each row's `fill`, falling back to the cycling palette. Set
 * `donut` for a donut, `showLabels` to draw slice labels, `tooltip` for hover.
 *
 * @example
 * ```html
 * <pie-chart [data]="data" nameKey="browser" dataKey="visitors" [donut]="true" />
 * ```
 */
@Component({
  selector: 'pie-chart',
  imports: [ChartFrame, Pie, ChartLegend],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    'data-slot': 'pie-chart',
    role: 'img',
    '[attr.aria-label]': 'ariaLabel()',
    '[class]': 'hostClass()',
  },
  template: `
    <div class="relative w-full">
      <div class="relative">
        <svg
          chartFrame
          [data]="data()"
          [xKey]="nameKey()"
          class="mx-auto aspect-square max-h-[260px] w-full overflow-visible text-muted-foreground"
        >
          <svg:g
            [pie]="dataKey()"
            [innerRadiusRatio]="donut() ? 0.6 : 0"
            #p="pie"
            [attr.transform]="p.transform()"
          >
            @for (s of p.slices(); track s.name) {
              <svg:path
                [attr.d]="s.d"
                [attr.fill]="sliceColor(s.index)"
                stroke="var(--background)"
                [attr.stroke-width]="active() === s.index ? 3 : 2"
                class="cursor-pointer"
                (pointerenter)="tooltip() && active.set(s.index)"
                (pointerleave)="active.set(null)"
              />
            }
            @if (showLabels()) {
              @for (l of p.labels(); track l.index) {
                <svg:text
                  [attr.x]="l.x"
                  [attr.y]="l.y"
                  text-anchor="middle"
                  dominant-baseline="middle"
                  class="pointer-events-none fill-background text-[10px] font-medium"
                >
                  {{ l.name }}
                </svg:text>
              }
            }
          </svg:g>
        </svg>

        @if (donut() && (centerValue() || centerLabel())) {
          <div
            data-slot="pie-chart-center"
            class="pointer-events-none absolute inset-0 flex flex-col items-center justify-center gap-0.5 text-center"
          >
            @if (centerValue()) {
              <span class="text-2xl font-semibold tabular-nums">{{
                centerValue()
              }}</span>
            }
            @if (centerLabel()) {
              <span class="text-xs text-muted-foreground">{{
                centerLabel()
              }}</span>
            }
          </div>
        }

        @if (tooltip() && active() !== null && p.labels()[active()!]) {
          <div
            class="pointer-events-none absolute z-10 min-w-24 -translate-x-1/2 -translate-y-1/2 rounded-sm border border-border bg-popover-surface px-2.5 py-1.5 text-xs shadow-md"
            [style.left.px]="p.center().cx + p.labels()[active()!].x"
            [style.top.px]="p.center().cy + p.labels()[active()!].y"
          >
            <div class="flex items-center gap-1.5 text-muted-foreground">
              <span
                class="size-2 rounded-[2px]"
                [style.background]="sliceColor(active()!)"
              ></span>
              <span>{{ activeName() }}</span>
              <span
                class="ml-auto pl-3 font-medium tabular-nums text-popover-foreground"
              >
                {{ activeValue() }}
              </span>
            </div>
          </div>
        }
      </div>

      @if (legend()) {
        <chart-legend [items]="legendItems()" />
      }

      <table class="sr-only">
        <caption>
          {{
            ariaLabel()
          }}
        </caption>
        <thead>
          <tr>
            <th>{{ nameKey() }}</th>
            <th>{{ dataKey() }}</th>
          </tr>
        </thead>
        <tbody>
          @for (row of data(); track $index) {
            <tr>
              <td>{{ row[nameKey()] }}</td>
              <td>{{ row[dataKey()] }}</td>
            </tr>
          }
        </tbody>
      </table>
    </div>
  `,
})
export class PieChart {
  readonly data = input.required<readonly ChartDatum[]>();
  readonly nameKey = input.required<string>();
  readonly dataKey = input.required<string>();
  readonly config = input<ChartConfig>({});
  readonly donut = input(false);
  readonly showLabels = input(false);
  readonly tooltip = input(true);
  /** Big figure in the donut hole, e.g. a total. Needs `donut`. */
  readonly centerValue = input<string>();
  /** Caption under `centerValue`, e.g. "spent this month". */
  readonly centerLabel = input<string>();
  /** Draw the chart's own card frame. Turn off when it sits inside a Card. */
  readonly framed = input(true);
  /** Show the color legend. Turn off when the page already lists the slices. */
  readonly legend = input(true);

  protected readonly hostClass = computed(() =>
    this.framed()
      ? 'flex flex-col gap-3 rounded-xl border border-border bg-card p-4 text-card-foreground'
      : 'flex flex-col gap-3',
  );

  readonly active = signal<number | null>(null);

  protected sliceColor(i: number): string {
    return (this.data()[i]?.fill as string | undefined) ?? paletteColor(i);
  }

  readonly legendRows = computed<LegendItem[]>(() =>
    this.data().map((row, i) => ({
      name: String(row[this.nameKey()]),
      color: this.sliceColor(i),
    })),
  );

  readonly activeName = computed(() => {
    const i = this.active();
    return i === null ? '' : String(this.data()[i]?.[this.nameKey()] ?? '');
  });

  readonly activeValue = computed(() => {
    const i = this.active();
    if (i === null) return '';
    const cfg = this.config()[this.dataKey()];
    return formatValue(
      Number(this.data()[i]?.[this.dataKey()] ?? 0),
      cfg?.format || 'number',
    );
  });

  readonly ariaLabel = computed(
    () =>
      `${this.donut() ? 'Donut' : 'Pie'} chart of ${this.dataKey()} by ${this.nameKey()}`,
  );

  /**
   * Adapts this chart's per-row legend to the shared legend component. These
   * charts colour by row rather than by series, so there is no per-series
   * `icon` to forward — the swatch is always the right mark here.
   */
  protected readonly legendItems = computed<ChartLegendItem[]>(() =>
    this.legendRows().map((item) => ({
      key: item.name,
      label: item.name,
      color: item.color,
    })),
  );
}
